    public OrganizationConfigController(TenantPolicyService policyService) {
        this.policyService = policyService;
    }

    // Flawed SpEL: checks role TENANT_ADMIN globally but does not assert #tenantId matches caller tenant
    @PutMapping("/{tenantId}/security-policy")
    @PreAuthorize("hasRole('TENANT_ADMIN')")
    public ResponseEntity<String> updateTenantSecurityPolicy(
            @PathVariable UUID tenantId,
