package com.saas.control.controller;

import com.saas.control.dto.TenantSecurityPolicyDto;
import com.saas.control.service.TenantPolicyService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;
import java.util.UUID;

@RestController
@RequestMapping("/admin/tenants")
public class OrganizationConfigController {

    private final TenantPolicyService policyService;

    public OrganizationConfigController(TenantPolicyService policyService) {
        this.policyService = policyService;
    }

    @PutMapping("/{tenantId}/security-policy")
    @PreAuthorize("hasRole('TENANT_ADMIN') and #tenantId.toString().equals(principal.tenantId)")
    public ResponseEntity<String> updateTenantSecurityPolicy(
            @PathVariable UUID tenantId,
            @RequestBody TenantSecurityPolicyDto policyDto) {
        policyService.applySecurityPolicy(tenantId, policyDto);
        return ResponseEntity.ok("Security policy updated for tenant");
    }
}
